ntc_capfind:	jp 243
kw_bssinit:	jp 291
ntc_plat_irqon:	jp 316
fs_go0:		jp 318
fs_go:		jp 319
fs_devices:	jp 320
fs_curdev:	jp 321
fs_volumes:	jp 323
fs_curvol:	jp 324
fs_load:		jp 327
fs_save:		jp 328
fs_err:		jp 337
fs_start:	jp 338
fs_namevol:	jp 339
fs_name:		jp 340
kw_waitkey:	jp 344
NTC_RJ_N	equ 32		; entries
FS_FAILED	equ #FFF7		; ROM const
FS_NOTFOUND	equ #FFFE		; ROM const
fs_a1	equ #893C		; ROM data
fs_a2	equ #893E		; ROM data
fs_a3	equ #8940		; ROM data
fs_buf	equ #9B05		; ROM const
fs_hmode	equ #894F		; ROM data
fs_res	equ #8942		; ROM data
ntc_csp	equ #8800		; ROM data
ntc_font	equ #948E		; ROM bss
ntc_nmode	equ #8807		; ROM data
