glyph_51			equ ntc_font + 392		; "Q"
glyph_52			equ ntc_font + 400		; "R"
glyph_53			equ ntc_font + 408		; "S"
glyph_54			equ ntc_font + 416		; "T"
glyph_55			equ ntc_font + 424		; "U"
glyph_56			equ ntc_font + 432		; "V"
glyph_58			equ ntc_font + 448		; "X"
